function safeGitHub(value,repo=true){try{const u=new URL(String(value||'').trim());return u.protocol==='https:'&&u.hostname==='github.com'&&!u.port&&!u.username&&!u.password&&u.pathname.split('/').filter(Boolean).length>=(repo?2:1)?u.href:''}catch{return ''}}
function normalizeTools(raw){const values=Array.isArray(raw)?raw:DEFAULT_TOOLS,seen=new Set();return values.slice(0,60).filter(t=>{if(!t||!/^tool-[a-z0-9-]{1,60}$/.test(t.id)||seen.has(t.id))return false;seen.add(t.id);return true}).map(t=>({id:t.id,kind:TOOL_KINDS.includes(t.kind)?t.kind:'其他',title:String(t.title||'未命名工具').slice(0,80),summary:String(t.summary||'').slice(0,1200),github:safeGitHub(t.github)}))}
function contentKeys(value){return new Set([...BASE_PROJECTS.flatMap(p=>[p.id+':cover',...p.slots.map(s=>p.id+':'+s[0]),...(p.artGroups||[]).flatMap(g=>g.items.map(item=>p.id+':'+item.key))]),...(value.tools||[]).flatMap(t=>[t.id+':cover',t.id+':demo'])])}
function syncContentKeys(){validKeys.clear();for(const key of contentKeys(state))validKeys.add(key)}
function toolArtwork(kind){const geometry=kind==='ComfyUI'?'<rect x="45" y="38" width="72" height="52" rx="4"/><rect x="180" y="68" width="72" height="52" rx="4"/><rect x="314" y="38" width="72" height="52" rx="4"/><path d="M117 64C152 64 145 94 180 94M252 94C282 94 282 64 314 64"/><circle cx="117" cy="64" r="3"/><circle cx="180" cy="94" r="3"/><circle cx="252" cy="94" r="3"/><circle cx="314" cy="64" r="3"/>':kind==='Blender'?'<path d="m216 20 64 35v67l-64 35-64-35V55Zm-64 35 64 36 64-36M216 91v66M184 38l64 36v67M248 38l-64 36v67M152 89l64 35 64-35"/>':kind==='Unity'?'<path d="M105 88h80m62 0h80M156 88v-45h58m-58 45v45h58"/><rect x="185" y="65" width="62" height="46" rx="3"/><circle cx="105" cy="88" r="6"/><circle cx="327" cy="88" r="6"/><circle cx="218" cy="43" r="4"/><circle cx="218" cy="133" r="4"/>':'<path d="m160 60-28 28 28 28m112-56 28 28-28 28m-45-70-24 140"/>';return `<svg viewBox="0 0 432 176" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.3">${geometry}</g></svg>`}
function renderTechnical(){const tools=state.tools||[];$('#technical-count').textContent=String(tools.length).padStart(2,'0');$('#tool-grid').innerHTML=tools.map(t=>{const repo=safeGitHub(t.github),preview=assets.has(t.id+':demo')?t.id+':demo':assets.has(t.id+':cover')?t.id+':cover':null;return `<article class="tool-card"><div class="tool-card-top"><span>${escapeHTML(t.kind)}</span><small>${preview||repo?'已添加内容':'预留位置'}</small></div><div class="tool-visual">${preview?visualHTML(t,preview,true):toolArtwork(t.kind)}</div><div class="tool-info"><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.summary)}</p>${repo?`<a class="tool-repository" href="${escapeHTML(repo)}" target="_blank" rel="noopener noreferrer">GitHub 仓库 <span aria-hidden="true">↗</span></a>`:'<span class="tool-repository pending">GitHub 仓库待补充</span>'}</div></article>`}).join('');$('#tools-empty').hidden=!!tools.length;const github=safeGitHub(state.githubProfile,false),link=$('#technical-github');link.hidden=!github;if(github)link.href=github}
const TECHNOLOGY_ENABLED=document.body.dataset.technologyHidden!=='true';
function selectPortfolio(module,updateHash=false){const tech=TECHNOLOGY_ENABLED&&module==='technology';if(!TECHNOLOGY_ENABLED&&location.hash==='#technology')history.replaceState(null,'','#works');$$('[data-module]').forEach(b=>{const on=(b.dataset.module==='technology')===tech;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});$('#art-panel').hidden=tech;$('#technology-panel').hidden=!tech;$('#module-description').textContent=tech?'制作工具、编辑器扩展与可复用工作流。':'游戏、VR 与 AI 实时内容，从资产制作到引擎实现。';document.querySelectorAll('.works video').forEach(v=>v.pause());if(updateHash)history.replaceState(null,'',tech?'#technology':'#works')}
function collectToolDrafts(){return [...document.querySelectorAll('[data-tool-editor]')].map(el=>({id:el.dataset.toolEditor,kind:el.querySelector('[data-tool-kind]').value,title:el.querySelector('[data-tool-title]').value.trim()||'未命名工具',summary:el.querySelector('[data-tool-summary]').value.trim(),github:el.querySelector('[data-tool-github]').value.trim()}))}
function renderToolManager(drafts=state.tools){$('#edit-github-profile').value=state.githubProfile||'';$('#manager-tools').innerHTML=drafts.map(t=>`<details class="manager-project tool-editor" data-tool-editor="${t.id}"><summary>${escapeHTML(t.title)}<small>技术 / ${escapeHTML(t.kind)}</small></summary><div class="manager-fields"><div class="form-row"><label>工具名称<input data-tool-title maxlength="80" value="${escapeHTML(t.title)}"></label><label>工具分类<select data-tool-kind>${TOOL_KINDS.map(k=>`<option ${k===t.kind?'selected':''}>${k}</option>`).join('')}</select></label></div><label>简短介绍<textarea data-tool-summary maxlength="1200">${escapeHTML(t.summary)}</textarea></label><label>GitHub 仓库链接<input type="url" data-tool-github value="${escapeHTML(t.github)}" placeholder="https://github.com/用户名/仓库名"></label><div class="upload-grid">${uploadField(t,'cover','工具封面 / 工作流截图')}${uploadField(t,'demo','工具演示 / 视频或图像')}</div><button type="button" class="tool-remove" data-remove-tool="${t.id}">移除此工具</button></div></details>`).join('');$('#manager-tools').querySelectorAll('[data-upload]').forEach(input=>input.onchange=()=>uploadAsset(input));$('#manager-tools').querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>removeAsset(button.dataset.remove));$('#manager-tools').querySelectorAll('[data-remove-tool]').forEach(button=>button.onclick=async()=>{const drafts=collectToolDrafts().filter(t=>t.id!==button.dataset.removeTool);try{const next={...state,tools:normalizeTools(drafts)};await dbWrite('state',next);state=next;syncContentKeys();renderToolManager();renderTechnical();setStatus('工具已移除。原有备份可用于恢复。')}catch(error){setStatus(errorMessage(error))}})}
function initializePortfolioModules(){$$('[data-module]').forEach(b=>{b.onclick=()=>selectPortfolio(b.dataset.module,true);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(!TECHNOLOGY_ENABLED){selectPortfolio('art',true);document.querySelector('[data-module="art"]').focus();return}const module=e.key==='Home'?'art':e.key==='End'?'technology':b.dataset.module==='art'?'technology':'art';selectPortfolio(module,true);document.querySelector(`[data-module="${module}"]`).focus()}}});$$('[data-nav-module]').forEach(a=>a.onclick=()=>selectPortfolio(a.dataset.navModule));window.addEventListener('hashchange',()=>{if(location.hash==='#technology'||location.hash==='#works')selectPortfolio(location.hash==='#technology'?'technology':'art')});$('#add-tool').onclick=async()=>{const drafts=collectToolDrafts();if(drafts.length>=60){setStatus('工具数量上限为 60。');return}const tool={id:'tool-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),kind:'其他',title:'新的制作工具',summary:'',github:''};try{const next={...state,tools:normalizeTools([...drafts,tool])};await dbWrite('state',next);state=next;syncContentKeys();renderToolManager();renderTechnical();const editor=document.querySelector(`[data-tool-editor="${tool.id}"]`);editor.open=true;editor.querySelector('[data-tool-title]').focus();setStatus('已新增工具，可以补充素材和 GitHub 链接。')}catch(error){setStatus(errorMessage(error))}};selectPortfolio(location.hash==='#technology'?'technology':'art')}

function legacyGalleryHTML(p){const filled=p.slots.filter(([key])=>assets.has(p.id+':'+key));if(!filled.length)return '';return `<h3 class="detail-gallery-heading">作品画面</h3><div class="detail-gallery legacy-gallery">${filled.map(([key,label])=>{const id=p.id+':'+key,item=assets.get(id),image=item.type.startsWith('image/');return `<figure class="gallery-slot ${image?'gallery-image':'gallery-video'}">${image?`<button type="button" class="slot-visual" data-zoom-asset="${id}" data-caption="${escapeHTML(label)}" aria-label="放大查看${escapeHTML(label)}">${visualHTML(p,id)}<span class="gallery-enlarge" aria-hidden="true">↗</span></button>`:`<div class="slot-visual">${visualHTML(p,id,true)}</div>`}<figcaption>${escapeHTML(label)}</figcaption></figure>`}).join('')}</div>`}
async function seedLegacyMedia(){for(const item of [...LEGACY_MEDIA,...BUILTIN_MEDIA]){if(!validKeys.has(item.key))continue;const previous=assets.get(item.key);if(previous?.blob&&previous.name===item.name&&/^assets\/media\/[a-f0-9]{20}\./.test(item.data)&&window.crypto?.subtle){try{const digest=await crypto.subtle.digest('SHA-256',await previous.blob.arrayBuffer());const hash=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,20);if(item.data.includes('/'+hash+'.')){assets.delete(item.key);if(db)await dbRemove('asset:'+item.key)}}catch{}}if(!assets.has(item.key)&&!(db&&await dbRead('hidden:'+item.key))){assets.set(item.key,{url:item.data,name:item.name,type:item.type})}}}
function mountLegacyProfile(){const resume=$('#download-resume');if(resume){resume.href=LEGACY_PROFILE.resume.startsWith('data:')?URL.createObjectURL(fromDataURL(LEGACY_PROFILE.resume,'application/pdf')):LEGACY_PROFILE.resume;resume.download='王立焱-简历.pdf'}document.addEventListener('click',e=>{const button=e.target.closest('[data-zoom-asset]');if(!button)return;const key=button.dataset.zoomAsset;if(!assets.has(key))return;const dialog=$('#image-dialog');$('#image-caption').textContent=button.dataset.caption;const img=$('#expanded-image');img.src=assetURL(key);img.alt=button.dataset.caption;dialog.showModal();dialog.querySelector('.image-scroll').scrollTop=0})}

