// Only content-addressed images and GIFs enter this bounded, on-demand cache.
const MEDIA_CACHE='portfolio-media-v1', mediaRequests=new Map();
async function cachedMediaURL(url){
  if(!/^assets\/(media|previews)\/[a-f0-9]{20}\.(webp|jpg|gif)$/.test(url))return url;
  if(mediaRequests.has(url))return mediaRequests.get(url);
  const request=(async()=>{
    try{
      const cache=await caches.open(MEDIA_CACHE);
      let response=await cache.match(url);
      if(!response){
        response=await fetch(url);
        if(!response.ok)throw new Error('素材加载失败');
        try{
          await cache.put(url,response.clone());
          const keys=await cache.keys();
          for(const key of keys.slice(0,Math.max(0,keys.length-128)))await cache.delete(key);
        }catch{/* Storage denial or quota must never prevent viewing. */}
      }
      return URL.createObjectURL(await response.blob());
    }catch{return url}
  })();
  mediaRequests.set(url,request);return request;
}
function previewImageHTML(url,alt='',full=false,extra=''){
  const thumb=!full&&MEDIA_THUMBS[url],src=thumb?thumb.src:url;
  return `<img data-media-src="${escapeHTML(src)}" alt="${escapeHTML(alt)}" loading="lazy" decoding="async" ${thumb?`width="${thumb.width}" height="${thumb.height}"`:''} ${extra}>`;
}
const lazyMediaObserver=new IntersectionObserver(entries=>{
  for(const {target,isIntersecting}of entries){
    if(!isIntersecting)continue;lazyMediaObserver.unobserve(target);
    const url=target.dataset.mediaSrc;delete target.dataset.mediaSrc;
    cachedMediaURL(url).then(src=>{if(target.isConnected)target.src=src});
  }
},{rootMargin:'160px'});
function observeMedia(parent=document){
  for(const img of parent.querySelectorAll('img[data-media-src]'))lazyMediaObserver.observe(img);
}
new MutationObserver(()=>observeMedia()).observe(document.body,{childList:true,subtree:true});
function gifPreviewHTML(preview,title,fullURL){
  if(!preview)return '';
  const seconds=Math.round((preview.seconds||4)*10)/10;
  const reduce=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  const src=reduce?preview.poster:preview.src;
  const actions=reduce||fullURL?`<div class="gif-preview-actions">${reduce?`<button type="button" data-gif-toggle aria-pressed="false">播放动图 · ${seconds} 秒</button>`:''}${fullURL?`<a href="${escapeHTML(fullURL)}" target="_blank" rel="noopener noreferrer">打开原视频 ↗</a>`:''}</div>`:'';
  return `<div class="gif-preview gif-preview-autoplay" data-gif="${escapeHTML(preview.src)}" data-poster="${escapeHTML(preview.poster)}" data-seconds="${seconds}">${previewImageHTML(src,title,true,'class="project-media"')}${actions}</div>`;
}
function gifAutoplayHTML(preview,title){
  if(!preview)return '';
  const reduce=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  const src=reduce?preview.poster:preview.src;
  return `<div class="gif-preview gif-preview-autoplay">${previewImageHTML(src,title,true,'class="project-media"')}</div>`;
}
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-gif-toggle]');if(!button)return;
  const root=button.closest('.gif-preview'),img=root.querySelector('img');
  const play=button.getAttribute('aria-pressed')!=='true';button.disabled=true;
  lazyMediaObserver.unobserve(img);delete img.dataset.mediaSrc;
  const src=await cachedMediaURL(play?root.dataset.gif:root.dataset.poster);
  if(root.isConnected){img.src=src;button.setAttribute('aria-pressed',String(play));button.textContent=play?'暂停动图':'播放动图 · '+(root.dataset.seconds||4)+' 秒'}
  button.disabled=false;
});
// Export deliberately resolves external media only after the user requests a file.
async function inlineMediaForExport(js){
  const paths=[...new Set([...js.matchAll(/["'](assets\/(?:media|previews)\/[a-f0-9]{20}\.(?:webp|jpg|mp4|pdf|gif))["']/g)].map(x=>x[1]))];
  for(const path of paths){const r=await fetch(path);if(!r.ok)throw new Error('导出素材失败：'+path);const data=await blobToDataURL(await r.blob());js=js.split('"'+path+'"').join('"'+data+'"').split("'"+path+"'").join("'"+data+"'")}
  return js;
}

