function renderCapabilities(){const config=state.capabilities||DEFAULT_CAPABILITIES;$('#capability-board').innerHTML=[['software','Software','软件与制作环境'],['programming','Programming','编程与材质节点'],['skills','Skills','核心制作能力']].map(([key,title,subtitle])=>`<article class="capability-panel capability-${key}" aria-labelledby="capability-${key}-title"><div class="capability-panel-heading"><h3 id="capability-${key}-title">${title}</h3><p>${subtitle}</p></div><ul class="${key==='skills'?'capability-skill-grid':'capability-icon-grid'}">${config[key].map(name=>{const meta=CAPABILITY_META[name]||{},linked=meta.project||(TECHNOLOGY_ENABLED&&meta.module);const content=capabilityIcon(name,key)+`<span class="capability-name">${escapeHTML(name)}</span>`;return `<li>${linked?`<button type="button" class="capability-item" ${meta.project?`data-capability-project="${meta.project}"`:'data-capability-module="technology"'} aria-label="${escapeHTML(name)}：查看相关${meta.project?'作品':'工具与工作流'}" ${meta.hint?`title="${escapeHTML(meta.hint)}"`:''}>${content}<span class="capability-item-arrow" aria-hidden="true">↗</span></button>`:`<div class="capability-item capability-static" ${meta.hint?`title="${escapeHTML(meta.hint)}"`:''}>${content}</div>`}</li>`}).join('')}</ul></article>`).join('');$('#capability-board').querySelectorAll('[data-capability-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.capabilityProject));$('#capability-board').querySelectorAll('[data-capability-module]').forEach(b=>b.onclick=()=>{selectPortfolio('technology',true);$('#works').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})}
function renderCapabilityEditor(){const config=state.capabilities||DEFAULT_CAPABILITIES;for(const key of ['software','programming','skills'])$('#edit-capabilities-'+key).value=config[key].join('\n')}
function collectCapabilities(){return normalizeCapabilities(Object.fromEntries(['software','programming','skills'].map(key=>[key,$('#edit-capabilities-'+key).value.split(/\r?\n/)])))}

