function dbRead(key){return new Promise((resolve,reject)=>{const r=db.transaction('content').objectStore('content').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbWrite(key,value){return new Promise((resolve,reject)=>{if(!db){reject(new Error('本地存储不可用，请保持页面打开并导出备份'));return}const tx=db.transaction('content','readwrite');tx.objectStore('content').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('保存中断'))})}
function dbRemove(key){return new Promise((resolve,reject)=>{if(!db){reject(new Error('本地存储不可用'));return}const tx=db.transaction('content','readwrite');tx.objectStore('content').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function normalizeState(raw){if(!raw||raw.version!==1||!Array.isArray(raw.projects))throw new Error('备份格式或版本不正确');return {version:1,capabilities:normalizeCapabilities(raw.capabilities),tools:normalizeTools(raw.tools),githubProfile:safeGitHub(raw.githubProfile,false),email:typeof raw.email==='string'?raw.email.slice(0,254):'',hero:BASE_PROJECTS.some(p=>p.id===raw.hero)?raw.hero:'',projects:BASE_PROJECTS.map(p=>{const saved=raw.projects.find(x=>x&&x.id===p.id)||{};return{id:p.id,title:typeof saved.title==='string'&&!(p.id==='evil-hero'&&saved.title==='邪恶勇者')&&!(p.id==='turtle-soup'&&saved.title==="海龟汤 · 汤之馆")?saved.title.slice(0,80):p.title,summary:typeof saved.summary==='string'&&!(p.id==='evil-hero'&&saved.summary==="全部模型资产由 Tripo 生成，经 Blender 修复与整理后导入 Unity，应用于角色、怪物、武器及森林与熔岩战场。")&&!(p.id==='nba'&&saved.summary==="围绕元宇宙空间，制作场景、角色服饰、材质、特效和 UI，并实现投篮小游戏。")&&!(p.id==='turtle-soup'&&saved.summary==="基于 Unity 构建沉浸式桌面推理体验，探索案件叙事、四向界面、手势与语音交互，以及受控 AI 主持。从策划与视觉生成到程序集成和运行验证，建立可复用的 AI 协同开发流程。")&&!(p.id==='evil-hero'&&saved.summary==="低多边形角色与武器资产、多视图展示，以及森林与熔岩环境中的多人玩法体验。")&&!(p.id==='turtle-soup'&&["以迷雾、石屋与烛光组织开场演出，将八席玩家注册、故事选择和四向推理界面串成桌面体验。","个人独立完成策划、内容设计与 Unity 开发，融合桌面推理、四向交互和迷雾烛光演出。","个人独立完成策划、美术与 Unity 开发。面向多人投影桌面，实现流动烟雾、木桌刻痕 Shader、四主题灯光与手势交互反馈。"].includes(saved.summary))?saved.summary.slice(0,1200):p.summary}})}}
function projectData(){return BASE_PROJECTS.map(p=>({...p,...state.projects.find(x=>x.id===p.id)}))}
function assetURL(key){const item=assets.get(key);if(!item)return null;if(item.url)return item.url;if(!urls.has(key))urls.set(key,URL.createObjectURL(item.blob));return urls.get(key)}
function releaseURL(key){if(urls.has(key)){URL.revokeObjectURL(urls.get(key));urls.delete(key)}}
