function visualHTML(p,key=p.id+':cover',controls=false){const asset=assets.get(key),url=assetURL(key);if(!asset)return `<div class="project-art">${makeArt(p.art)}</div>`;if(asset.type.startsWith('video/')){if(key==='evil-hero:gameplay'&&asset.url)return gifPreviewHTML(GIF_PREVIEWS['evil-hero'],p.title,PROJECT_VIDEO_LINKS['evil-hero'][0].url);return `<video class="project-media" src="${url}" preload="none" muted playsinline ${controls?'controls':''} aria-label="${escapeHTML(p.title)}视频"></video>`}return previewImageHTML(url,p.title,controls,'class="project-media"')}
function renderProjects(){const count=$('.section-count'),allCount=$('[data-filter="all"] span');if(count)count.textContent=String(BASE_PROJECTS.length).padStart(2,'0');if(allCount)allCount.textContent=BASE_PROJECTS.length;const projects=projectData().filter(p=>filter==='all'||p.filters.includes(filter));$('#project-grid').innerHTML=projects.map(p=>p.id==='dark-forest'?forestProjectHTML(p):`<article class="project-card" data-project="${p.id}"><button class="project-open" data-open="${p.id}" aria-label="查看${escapeHTML(p.title)}项目详情">${projectCoverHTML(p)}${assets.has(p.id+':cover')?'':'<span class="placeholder-badge">视觉占位 / 待补原始素材</span>'}<span class="project-open-arrow" aria-hidden="true">↗</span></button><div class="project-info"><p class="project-category">${escapeHTML(p.category)}</p><h3><button data-open="${p.id}">${escapeHTML(p.title)}</button></h3><p class="project-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(t=>'<span>'+escapeHTML(t)+'</span>').join('')}</div></div></article>`).join('');$$('[data-open]').forEach(b=>b.onclick=e=>{e.preventDefault();openProject(b.dataset.open)});for(const task of [renderContact,renderHero,renderTechnical,renderCapabilities,mountCharacterComparisons,mountForestShowcases]){try{Promise.resolve(task()).catch(error=>console.warn('Optional project enhancement failed',error))}catch(error){console.warn('Optional project enhancement failed',error)}}}
function renderContact(){const email=safeEmail(state.email);$('#contact-link').hidden=!email;$('#contact-pending').hidden=!!email;if(email)$('#contact-link').href='mailto:'+email}
function renderHero(){const v=$('#hero-viewport'),p=projectData().find(p=>p.id===state.hero);v.querySelector('.hero-upload')?.remove();const filled=p&&assets.has(p.id+':cover');v.classList.toggle('hero-has-media',!!filled);$('#lab-canvas').hidden=!!filled;if(filled){const div=document.createElement('div');div.className='hero-upload';div.innerHTML=visualHTML(p,p.id+':cover',false);v.appendChild(div);const video=div.querySelector('video');if(video){video.loop=true;video.muted=true;if(!paused)video.play().catch(()=>{})}}}
function turtleTAProcessHTML(p,validation=false){const t=p.taProcess;if(!t)return '';if(validation)return `<section class="turtle-process"><h3>验证记录 · 更新开销与可重建性</h3><div class="technical-breakdown">${t.evidence.map(([title,value,text])=>`<article><h4>${escapeHTML(title)}</h4><strong class="ta-metric">${escapeHTML(value)}</strong><p>${escapeHTML(text)}</p></article>`).join('')}</div><p class="turtle-art-description">${escapeHTML(t.scope)}</p><a class="button" href="${escapeHTML(t.pdf)}" target="_blank" rel="noopener noreferrer">查看项目展示稿 · PDF ↗</a></section>`;return `<section class="turtle-process"><h3>AI 协同 · 技术美术工作流</h3><p class="turtle-art-description">${escapeHTML(t.intro)}</p><ol class="ta-workflow">${t.workflow.map(([title,text])=>`<li><h4>${escapeHTML(title)}</h4><p>${escapeHTML(text)}</p></li>`).join('')}</ol><div class="technical-breakdown">${t.decisions.map(([title,text])=>`<article><h4>${escapeHTML(title)}</h4><p>${escapeHTML(text)}</p></article>`).join('')}</div></section>`}
function turtleArtGalleryHTML(p){return (p.artGroups||[]).map(group=>`<section class="turtle-art-group"><h3>${escapeHTML(group.title)}</h3><p class="turtle-art-description">${escapeHTML(group.text)}</p><div class="detail-gallery turtle-art-grid ${group.items.length===3?'turtle-art-triple':''}">${group.items.filter(item=>assets.has(p.id+':'+item.key)).map(item=>{const key=p.id+':'+item.key;return `<figure class="gallery-slot gallery-image"><button type="button" class="slot-visual" data-zoom-asset="${key}" data-caption="${escapeHTML(item.title)}" aria-label="放大查看${escapeHTML(item.title)}">${previewImageHTML(assetURL(key),item.title,false,'class="project-media"')}<span class="gallery-enlarge" aria-hidden="true">↗</span></button><figcaption>${escapeHTML(item.title)}</figcaption></figure>`}).join('')}</div></section>`).join('')}
function turtleTopicMediaHTML(p,items){return `<div class="detail-gallery turtle-art-grid">${items.filter(item=>assets.has(p.id+':'+item[0])).map(([key,title])=>`<figure class="gallery-slot gallery-image"><button type="button" class="slot-visual" data-zoom-asset="${p.id+':'+key}" data-caption="${escapeHTML(title)}" aria-label="放大查看${escapeHTML(title)}">${previewImageHTML(assetURL(p.id+':'+key),title,false,'class="project-media"')}<span class="gallery-enlarge" aria-hidden="true">↗</span></button><figcaption>${escapeHTML(title)}</figcaption></figure>`).join('')}</div>`}
function openTurtleSoup(p){activeProject=p.id;const candle=GIF_PREVIEWS['turtle-candle'],opening=GIF_PREVIEWS['turtle-opening'],t=p.taProcess;
const topic=(n,title,text,media)=>`<section class="turtle-topic" aria-labelledby="turtle-topic-${n}"><p class="eyebrow">TECHNICAL ART / ${n}</p><h3 id="turtle-topic-${n}">${title}</h3><p class="turtle-art-description">${text}</p>${media}</section>`;
$('#project-detail').innerHTML=`<div class="detail-hero">${visualHTML(p,'turtle-soup:voice-overview',true)}</div><div class="detail-content turtle-case-study"><p class="project-category">${escapeHTML(p.category)}</p><h2>${escapeHTML(p.title)}</h2><p class="detail-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(tag=>'<span>'+escapeHTML(tag)+'</span>').join('')}</div><p class="turtle-art-description">个人负责视觉拆解、生成素材落地、Shader 与交互演出、编辑器工具和运行验证。下方按技术点对应展示。</p>
${topic('01','烟雾与开场 · 轮廓、流动、显隐分开控制','用 2.5D 透明雾层保留石屋轮廓与中央留白；Flow Map 扰动和双相位采样组织流动，C# 控制镜头、散雾与点灯。下方依次对应效果剪辑、烟雾轮廓与流向输入。',opening?`<figure class="turtle-motion"><figcaption>Unity 开场运行剪辑 · ${opening.seconds||33.32} 秒</figcaption>${gifPreviewHTML(opening,opening.title)}</figure>`+turtleTopicMediaHTML(p,[['ta-smoke-texture','烟雾贴图 · Alpha 轮廓'],['ta-flow-map','RG 流向图 · 扰动输入']]):'')}
${topic('02','烛火交互 · 输入驱动顶端形变','指针划过烛焰时，以 Shader 顶端位移形成弯曲，再通过弹簧回弹恢复。现有动图展示指针交互；语音、手势 SDK 的真实设备体验需另行展示。',candle?`<figure class="turtle-motion"><figcaption>指针拨焰 · 现有运行记录</figcaption>${gifAutoplayHTML(candle,candle.title)}</figure>`:'')}
${topic('03','材质化 UI · 图案变成木桌刻痕','图案 Alpha 与偏移采样组合凹槽阴影、磨损亮边和铜色嵌线。左图为输入图案，右图为实机局部；着色模拟浅浮雕层次，不改变桌面几何。',turtleTopicMediaHTML(p,[['ta-ring-mask','输入 · 环形图案'],['ta-engraving-detail','输出 · 木桌刻痕与铜线，实机裁切']]))}
${topic('04','四主题氛围 · 同一镜头比较参数差异','保持同一讨论界面，比较标准、微恐、恐怖和娱乐主题的配色、烟雾与灯光。静帧展示视觉差异；动态节奏由共享时钟与主题参数控制，中央文字保持稳定。',turtleTopicMediaHTML(p,[['screen-10-theme-Standard','标准 · 同视角运行截图'],['screen-10-theme-MildHorror','微恐 · 同视角运行截图'],['screen-10-theme-Horror','恐怖 · 同视角运行截图'],['screen-10-theme-Entertainment','娱乐 · 同视角运行截图']]))}
${topic('05','AI 资产落地 · 从概念到分层界面','将墨石与断裂铜环拆成七张无字透明素材，文字保持实时可编辑，装饰与命中区域分离。同一套素材复用于语音和提示界面，宽窄铭板适配四向阅读。',turtleTopicMediaHTML(p,[['voice-assembly','制作 · 墨石与铜环，Unity 隔离渲染'],['voice-voice','落地 · 语音皮肤接入运行截图']])+`<details class="turtle-extra"><summary>概念探索与制作流程</summary>${turtleTopicMediaHTML(p,[['ta-concept-selection','AI 选案概念 · 非实机'],['screen-04-story-selection','Unity 选案 · 当前仅开放 SH001']])}<ol class="ta-workflow">${(t?.workflow||[]).map(([title,text])=>`<li><h4>${escapeHTML(title)}</h4><p>${escapeHTML(text)}</p></li>`).join('')}</ol></details>`)}
${topic('06','语音与 AI 主持 · 真实输入、规则受控','复用 SDK 的实际录音流驱动界面反馈，AI 主持负责对话，Unity 校验请求并控制次数、得分与成功条件。',`<div class="technical-breakdown"><article><h4>听得见的反馈</h4><p>PCM 音量驱动 48 条滚动柱，约 30 Hz 更新；展示音量包络。</p></article><article><h4>明确的等待状态</h4><p>持续无声 10 秒自动关闭且不扣次数；开始说话后继续识别，并区分收音、缓冲与 AI 判断。</p></article><article><h4>可核对的接入</h4><p>已有 43 项语音与连接隔离回归、6 项提示页生命周期检查及本机麦克风验证记录。</p></article></div>`)}
${topic('07','工具与验证 · 可重建、可检查的制作过程','ArtPass 统一素材导入、材质引用与布局，Builder 保留重建路径。下面的历史检查分别对应稳态刷新、空闲反馈与重复安装，不能据此推导 FPS 或 GPU 提升。',`<div class="technical-breakdown">${(t?.evidence||[]).map(([title,value,text])=>`<article><h4>${escapeHTML(title)}</h4><strong class="ta-metric">${escapeHTML(value)}</strong><p>${escapeHTML(text)}</p></article>`).join('')}</div><p class="source-note">${escapeHTML(t?.scope||'')}</p>`)}
<details class="turtle-extra"><summary>更多流程界面与叙事画面</summary>${legacyGalleryHTML({...p,slots:p.slots.filter(([key])=>key!=='screen-04-story-selection'&&!key.startsWith('voice-'))})}${turtleTopicMediaHTML(p,[['ta-concept-reading','AI 汤面概念 · 非实机'],['ta-reveal-illustration','五幕回放第二幕 · 后续运行验收截图']])}</details>
${t?.pdf?`<p><a class="button" href="${escapeHTML(t.pdf)}" target="_blank" rel="noopener noreferrer">查看项目展示稿 · PDF ↗</a></p>`:''}<p class="source-note">${escapeHTML(p.sourceNote)}</p></div>`;if(!$('#project-dialog').open)$('#project-dialog').showModal()}
function openProject(id){const p=projectData().find(x=>x.id===id);if(!p)return;$('#project-dialog').classList.remove('forest-dialog');if(id==='turtle-soup'){openTurtleSoup(p);return}if(id==='dark-forest'){openForest();return}if(id==='hangzhou-monopoly'){openMonopoly(p);return}activeProject=id;$('#project-detail').innerHTML=`<div class="detail-hero">${projectGifPreview(p)?gifAutoplayHTML(projectGifPreview(p),projectGifPreview(p).title||p.title):visualHTML(p,p.id+':cover',true)}${assets.has(p.id+':cover')?'':'<span class="placeholder-badge">视觉占位 / 非项目实机画面</span>'}</div><div class="detail-content"><p class="project-category">${escapeHTML(p.category)}</p><h2>${escapeHTML(p.title)}</h2><p class="detail-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(t=>'<span>'+escapeHTML(t)+'</span>').join('')}</div><div class="detail-columns"><div><h3>${p.id==='hangzhou-monopoly'?'可核实的工程实现':'作品内容与职责'}</h3><ul>${p.role.map(t=>'<li>'+escapeHTML(t)+'</li>').join('')}</ul></div><div>${p.id==='nba'?'':`<h3>${p.id==='evil-hero'?'制作流程与展示':'项目记录与待补细节'}</h3>`}<ul>${p.notes.map(t=>'<li>'+escapeHTML(t)+'</li>').join('')}</ul></div></div>${p.breakdown?`<div class="technical-breakdown">${p.breakdown.map(b=>`<article><h3>${escapeHTML(b.title)}</h3><p>${escapeHTML(b.text)}</p><small>${escapeHTML(b.evidence)}</small></article>`).join('')}</div>`:''}${['solar-vr','nba'].includes(p.id)?'<h3>动态预览</h3>'+gifPreviewHTML(GIF_PREVIEWS[p.id],p.title,PROJECT_VIDEO_LINKS[p.id][0].url):''}${legacyGalleryHTML(p)}${PROJECT_VIDEO_LINKS[p.id]?'<div class="project-video-links">'+PROJECT_VIDEO_LINKS[p.id].map(l=>'<a class="button" href="'+escapeHTML(l.url)+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(l.title)+' ↗</a>').join('')+'</div>':p.video?`<p><a class="button" href="${p.video}" target="_blank" rel="noopener noreferrer">打开作品集内视频链接 ↗</a></p>`:''}<p class="source-note">${p.sourceNote?escapeHTML(p.sourceNote):`内容依据：所提供作品集 PDF，第 ${p.pages} 页（文件页序）。视频链接来自作品集，外部链接可用性待核实。`}</p></div>`;if(!$('#project-dialog').open)$('#project-dialog').showModal()}
function uploadField(p,key,label){const id=p.id+':'+key,asset=assets.get(id);return `<div class="upload-field"><label>${escapeHTML(label)}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm" data-upload="${id}"></label><span class="upload-state" data-upload-status="${id}">${asset?escapeHTML(asset.name):'尚未添加素材'}</span><button type="button" class="remove-asset" data-remove="${id}" ${asset?'':'hidden'}>移除此素材</button></div>`}
function renderManager(){const projects=projectData();$('#edit-email').value=state.email;$('#edit-hero').innerHTML='<option value="">交互式波面占位</option>'+projects.map(p=>`<option value="${p.id}">${escapeHTML(p.title)}封面</option>`).join('');$('#edit-hero').value=state.hero;$('#manager-projects').innerHTML=projects.map((p,i)=>`<details class="manager-project" ${i===0?'open':''}><summary>${escapeHTML(p.title)}<small>${p.sourceLabel?escapeHTML(p.sourceLabel):`PDF 第 ${p.pages} 页`} / 封面 + ${p.slots.length} 个内容位置</small></summary><div class="manager-fields"><label>项目标题<input data-title="${p.id}" maxlength="80" required value="${escapeHTML(p.title)}"></label><label>项目简介<textarea data-summary="${p.id}" maxlength="1200">${escapeHTML(p.summary)}</textarea></label><div class="upload-grid">${uploadField(p,'cover','项目封面 / 首页素材')}${p.slots.map(([key,label])=>uploadField(p,key,label)).join('')}</div></div></details>`).join('');$$('[data-upload]').forEach(input=>input.onchange=()=>uploadAsset(input));$$('[data-remove]').forEach(button=>button.onclick=()=>removeAsset(button.dataset.remove));renderToolManager();renderCapabilityEditor();setStatus('支持 PNG / JPG / WebP / GIF / MP4 / WebM，每个文件不超过 150 MB。建议视频压缩至 50 MB 以下。素材选择后立即保存，文字修改请点击保存。')}
async function uploadAsset(input){const file=input.files[0],key=input.dataset.upload;if(!file)return;input.disabled=true;try{if(!MIME_TYPES.has(file.type))throw new Error('请使用 PNG、JPG、WebP、GIF、MP4 或 WebM 文件');if(file.size>MAX_FILE)throw new Error('文件超过 150 MB，请先压缩');const record={blob:file,name:file.name,type:file.type};await dbWrite('asset:'+key,record);await dbRemove('hidden:'+key);releaseURL(key);assets.set(key,record);document.querySelector(`[data-upload-status="${key}"]`).textContent=file.name;document.querySelector(`[data-remove="${key}"]`).hidden=false;renderProjects();setStatus('已保存素材：'+file.name);toast('素材已保存到当前浏览器')}catch(error){setStatus(errorMessage(error))}finally{input.disabled=false;input.value=''}}
async function removeAsset(key){try{await dbRemove('asset:'+key);await dbWrite('hidden:'+key,true);releaseURL(key);assets.delete(key);document.querySelector(`[data-upload-status="${key}"]`).textContent='尚未添加素材';document.querySelector(`[data-remove="${key}"]`).hidden=true;renderProjects();setStatus('素材已移除，可随时重新上传。')}catch(error){setStatus(errorMessage(error))}}
$('#manager-form').onsubmit=async e=>{e.preventDefault();const toolDrafts=collectToolDrafts(),profile=$('#edit-github-profile').value.trim();if(toolDrafts.some(t=>t.github&&!safeGitHub(t.github))||(profile&&!safeGitHub(profile,false))){setStatus('请填写有效的 https://github.com 仓库或主页链接。');return}const next={version:1,capabilities:collectCapabilities(),tools:normalizeTools(toolDrafts),githubProfile:safeGitHub(profile,false),email:$('#edit-email').value.trim(),hero:$('#edit-hero').value,projects:BASE_PROJECTS.map(p=>({id:p.id,title:document.querySelector(`[data-title="${p.id}"]`).value.trim()||p.title,summary:document.querySelector(`[data-summary="${p.id}"]`).value.trim()}))};try{await dbWrite('state',next);state=next;syncContentKeys();renderProjects();setStatus('文字与首页设置已保存。');toast('内容已保存')}catch(error){setStatus(errorMessage(error))}};
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
function fromDataURL(value,type){if(typeof value!=='string'||!value.startsWith('data:'+type+';base64,'))throw new Error('备份内素材格式不正确');const bytes=atob(value.slice(value.indexOf(',')+1));if(bytes.length>MAX_FILE)throw new Error('备份内含超过 150 MB 的素材');return new Blob([Uint8Array.from(bytes,c=>c.charCodeAt(0))],{type})}
async function packageContent(){const media=[];for(const [key,item]of assets)if(validKeys.has(key))media.push({key,name:item.name,type:item.type,data:await blobToDataURL(item.blob||await fetch(item.url).then(r=>{if(!r.ok)throw new Error('素材读取失败');return r.blob()}))});return{version:1,builtinSeeded:true,legacySeeded:true,snapshotId:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),state,media}}
function download(blob,filename){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}
async function performExport(button,task){button.disabled=true;setStatus('正在准备文件，请稍候…');try{await task();setStatus('导出已触发，请查看浏览器下载。未保存的文字不会包含在导出文件中。')}catch(error){setStatus(errorMessage(error))}finally{button.disabled=false}}
$('#export-backup').onclick=()=>performExport($('#export-backup'),async()=>download(new Blob([JSON.stringify(await packageContent())],{type:'application/json'}),'王立焱-站点内容备份.json'));
$('#export-site').onclick=()=>performExport($('#export-site'),async()=>{const [css,js,content]=await Promise.all([originalCSS(),originalJS().then(inlineMediaForExport),packageContent()]);if(!css||!js)throw new Error('页面源文件不可用，请通过本地预览地址打开后导出');const payload=JSON.stringify(content).replace(/</g,'\\u003c');let html=ORIGINAL_HTML.replace(/<script id="site-data" type="application\/json">[\s\S]*?<\/script>/,()=>'<script id="site-data" type="application/json">'+payload+'</script>');const style='<style id="application-style">'+css.replace(/<\/style/gi,'<\\/style')+'</style>';const code='<script id="application-code">'+js.replace(/<\/script/gi,'<\\/script')+'</script>';html=/<link rel="stylesheet" href="style\.css(?:\?[^"]*)?">/.test(html)?html.replace(/<link rel="stylesheet" href="style\.css(?:\?[^"]*)?">/,()=>style):html.replace(/<style id="application-style">[\s\S]*?<\/style>/,()=>style);html=/<script src="app\.js(?:\?[^"]*)?"(?: defer)?><\/script>/.test(html)?html.replace(/<script src="app\.js(?:\?[^"]*)?"(?: defer)?><\/script>/,()=>code):html.replace(/<script id="application-code">[\s\S]*?<\/script>/,()=>code);download(new Blob([html],{type:'text/html;charset=utf-8'}),'王立焱-个人站.html')});
$('#import-backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>400*1024*1024)throw new Error('备份过大，请使用较小的备份文件');const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.media))throw new Error('不是本站的内容备份');const next=normalizeState(raw.state),nextAssets=new Map();for(const item of raw.media){if(!contentKeys(next).has(item.key)||!MIME_TYPES.has(item.type)||nextAssets.has(item.key))throw new Error('备份包含无效或重复的素材位置');nextAssets.set(item.key,{blob:fromDataURL(item.data,item.type),name:String(item.name).slice(0,250),type:item.type})}if(!db)throw new Error('本地存储不可用');await new Promise((resolve,reject)=>{const tx=db.transaction('content','readwrite'),store=tx.objectStore('content');store.clear();store.put(next,'state');store.put(true,'builtin-seeded-monopoly');store.put(true,'builtin-seeded-legacy-v1');for(const [key,item]of nextAssets)store.put(item,'asset:'+key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('恢复失败'))});for(const key of urls.keys())releaseURL(key);state=next;syncContentKeys();assets=nextAssets;renderProjects();renderManager();setStatus('备份已恢复，替换了当前浏览器中本站的内容。')}catch(error){setStatus('恢复失败：'+errorMessage(error))}finally{e.target.value=''}};
$('#open-manager').onclick=()=>{renderManager();$('#manager-dialog').showModal()};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});dialog.addEventListener('close',()=>{dialog.querySelectorAll('video').forEach(v=>v.pause());if(dialog.id==='project-dialog')activeProject=null})});
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects()});

