function drawWave(){if(!heroGL||canvas.hidden)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;const dpr=Math.min(devicePixelRatio||1,innerWidth<700?1:1.25);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}heroGL.viewport(0,0,canvas.width,canvas.height);heroGL.useProgram(heroProgram);heroGL.uniform1f(heroTime,phase);heroGL.uniform2f(heroResolution,w,h);heroGL.uniform2f(heroPointer,pointer.x,pointer.y);heroGL.drawArrays(heroGL.TRIANGLE_STRIP,0,4);canvas.dataset.ready='true'}
function animate(time){requestAnimationFrame(animate);if(time-lastTime<(innerWidth<700?66:42))return;const dt=Math.min((time-lastTime)/1000,.1);lastTime=time;if(paused||document.hidden||canvas.hidden||canvas.getBoundingClientRect().bottom<0)return;phase+=dt;drawWave()}
