const characterWidgets=new Set();let characterResources=null;
function characterCompareHTML(){return `<section class="character-comparison" aria-label="八个角色动态形象对比"><div class="character-heading"><div><p class="eyebrow">八种性格，同台亮相</p><h3>角色动态对比</h3></div><div class="character-controls"><label class="character-speech-label"><input class="character-speech" type="checkbox" checked> 说话口型</label><button class="character-play" type="button">暂停</button><button class="character-replay" type="button">重播</button></div></div><div class="character-grid">${CHARACTER_DATA.map(c=>`<article class="character-card" style="--role-color:${c.color}"><div class="character-stage" data-role="${c.role}"><canvas aria-label="${c.name}动态形象"></canvas></div><h4>${c.name}</h4>${c.skill?`<p class="character-skill">${c.skill}</p>`:``}</article>`).join('')}</div><p class="character-note">前四名为网页分层预览；后四名西溪、云栖、湖滨、钱江使用工程表情序列 GIF，展示眨眼与说话。</p><p class="character-load-status" role="status">正在加载角色…</p></section>`}
const cClamp=(x,a,b)=>Math.max(a,Math.min(b,x));
