async function prepareCharacters(){if(characterResources)return characterResources;characterResources=Promise.all(CHARACTER_DATA.map(async c=>{const layers=await Promise.all(c.layers.map(async l=>{const image=await cImage(await cachedMediaURL(l.image)),tex=document.createElement('canvas');tex.width=image.width;tex.height=image.height;const tc=tex.getContext('2d',{willReadFrequently:true});tc.drawImage(image,0,0);if(l.backing){const backing=await cImage(await cachedMediaURL(l.backing)),bc=document.createElement('canvas');bc.width=tex.width;bc.height=tex.height;const bctx=bc.getContext('2d',{willReadFrequently:true});bctx.drawImage(backing,0,0,bc.width,bc.height);const src=tc.getImageData(0,0,tex.width,tex.height),back=bctx.getImageData(0,0,tex.width,tex.height);for(let y=0;y<tex.height;y++)for(let x=0;x<tex.width;x++){const u=x/tex.width,v=1-y/tex.height;let w=Math.max(cSmooth(.49,.51,v),(1-cSmooth(.30,.33,u))*cSmooth(.23,.25,v));w*=1-(u>=.665?1:0)*(1-cSmooth(.60,.63,v));const n=(y*tex.width+x)*4;for(let ch=0;ch<4;ch++)src.data[n+ch]=back.data[n+ch]*(1-w)+src.data[n+ch]*w}tc.putImageData(src,0,0)}if(l.slice){const pixels=tc.getImageData(0,0,tex.width,tex.height),line=l.line;for(let y=0;y<tex.height;y++)for(let x=0;x<tex.width;x++){const right=x/tex.width>=line.r+line.g*Math.min(1-y/tex.height,line.b);if(l.slice<1.5?right:!right)pixels.data[(y*tex.width+x)*4+3]=0}tc.putImageData(pixels,0,0)}const expressions=l.face?await Promise.all(['EyesHalf','EyesClosed','MouthAh','MouthO'].map(async k=>cImage(await cachedMediaURL(l.face[k])))):null;return{...l,texture:tex,expressions}}));return{...c,layers}}));return characterResources}
function cTriangle(ctx,texture,a,b,c,ta,tb,tc){const det=(tb[0]-ta[0])*(tc[1]-ta[1])-(tc[0]-ta[0])*(tb[1]-ta[1]);if(Math.abs(det)<.0001)return;const m0=((b[0]-a[0])*(tc[1]-ta[1])-(c[0]-a[0])*(tb[1]-ta[1]))/det,m2=((c[0]-a[0])*(tb[0]-ta[0])-(b[0]-a[0])*(tc[0]-ta[0]))/det,m1=((b[1]-a[1])*(tc[1]-ta[1])-(c[1]-a[1])*(tb[1]-ta[1]))/det,m3=((c[1]-a[1])*(tb[0]-ta[0])-(b[1]-a[1])*(tc[0]-ta[0]))/det;ctx.save();ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.lineTo(...c);ctx.closePath();ctx.clip();ctx.transform(m0,m1,m2,m3,a[0]-m0*ta[0]-m2*ta[1],a[1]-m1*ta[0]-m3*ta[1]);ctx.drawImage(texture,0,0);ctx.restore()}
