async function mountCharacterComparisons(parent=document){for(const root of parent.querySelectorAll('.character-comparison')){if(root.dataset.mounted)continue;root.dataset.mounted='true';const widget={root,action:'Idle',paused:matchMedia('(prefers-reduced-motion: reduce)').matches,start:performance.now(),progress:0,elapsed:0,speaking:true,resources:null};characterWidgets.add(widget);root.querySelector('.character-speech').onchange=e=>{widget.speaking=e.target.checked};const play=root.querySelector('.character-play');const sync=()=>{play.textContent=widget.paused?'播放':'暂停';play.setAttribute('aria-pressed',String(widget.paused))};sync();play.onclick=()=>{widget.paused=!widget.paused;widget.start=performance.now()-widget.elapsed*1000;sync();root.querySelectorAll('video').forEach(v=>widget.paused?v.pause():v.play().catch(()=>{}))};root.querySelector('.character-replay').onclick=()=>{widget.start=performance.now();widget.progress=0;widget.elapsed=0;widget.paused=false;sync();root.querySelectorAll('video').forEach(v=>{v.currentTime=0;v.play().catch(()=>{})})};const p=projectData().find(x=>x.id==='hangzhou-monopoly');for(const c of CHARACTER_DATA){const key='hangzhou-monopoly:'+c.slot;if(assets.has(key)){root.querySelector(`[data-role="${c.role}"]`).innerHTML=visualHTML(p,key,true)}}const observer=new IntersectionObserver(async entries=>{if(!entries.some(e=>e.isIntersecting))return;observer.disconnect();try{widget.resources=await prepareCharacters();root.querySelector('.character-load-status').textContent='';root.dataset.loaded='true';widget.start=performance.now()}catch(error){root.querySelector('.character-load-status').textContent=errorMessage(error)}},{rootMargin:'160px'});observer.observe(root)}}
let characterLast=0;function characterTick(time){requestAnimationFrame(characterTick);if(time-characterLast<65||document.hidden)return;characterLast=time;for(const widget of characterWidgets){if(!widget.root.isConnected){characterWidgets.delete(widget);continue}const r=widget.root.getBoundingClientRect();if(!widget.resources||r.bottom<0||r.top>innerHeight||!r.height)continue;if(document.querySelector('#project-dialog[open]')&&!widget.root.closest('dialog'))continue;if(!widget.paused){widget.elapsed=(time-widget.start)/1000;widget.progress=(widget.elapsed%4)/4;}for(const c of widget.resources){const canvas=widget.root.querySelector(`[data-role="${c.role}"] canvas`);if(canvas)drawCharacter(canvas,c,widget.action,widget.progress,widget.elapsed,widget.speaking)}}}requestAnimationFrame(characterTick);
function openMonopoly(p){activeProject=p.id;$('#project-detail').innerHTML=`${GIF_PREVIEWS['hangzhou-play']?`<div class="detail-hero hangzhou-detail-hero">${gifAutoplayHTML(GIF_PREVIEWS['hangzhou-play'],GIF_PREVIEWS['hangzhou-play'].title||'游玩方式')}</div>`:''}<div class="detail-content compact-project"><p class="project-category">${escapeHTML(p.category)}</p><h2>${escapeHTML(p.title)}</h2><p class="detail-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(t=>'<span>'+escapeHTML(t)+'</span>').join('')}</div>${characterCompareHTML()}${p.breakdown?`<div class="technical-breakdown">${p.breakdown.map(b=>`<article><h3>${escapeHTML(b.title)}</h3><p>${escapeHTML(b.text)}</p></article>`).join('')}</div>`:''}<h3 class="detail-gallery-heading">场景与界面</h3><div class="detail-gallery"><div class="gallery-slot"><div class="slot-visual">${visualHTML(p)}</div><p>棋盘全貌</p></div><div class="gallery-slot"><div class="slot-visual">${visualHTML(p,p.id+':cast')}</div><p>八角色选人</p></div><div class="gallery-slot"><div class="slot-visual">${visualHTML(p,p.id+':table')}</div><p>围桌对局</p></div><div class="gallery-slot"><div class="slot-visual">${visualHTML(p,p.id+':ui')}</div><p>房产明细 · 四向 UI</p></div></div><p class="source-note">${escapeHTML(p.sourceNote||'')}</p></div>`;if(!$('#project-dialog').open)$('#project-dialog').showModal();mountCharacterComparisons($('#project-dialog'))}

function forestDeckHTML(detail=false,start=0){return `<section class="forest-deck ${detail?'forest-deck-large':''}" data-start="${start}" aria-label="黑暗森林卡牌展示"><div class="forest-stage" aria-label="使用左右方向键切换卡牌" tabindex="0">${FOREST_CARDS.map((c,i)=>`<button class="forest-card" data-card="${i}" type="button" aria-label="查看${escapeHTML(c.title)}">${previewImageHTML(c.image,c.title+'卡牌',false,'draggable="false"')}</button>`).join('')}</div><div class="forest-toolbar"><button type="button" data-deck-step="-1" aria-label="上一张卡牌"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><div class="forest-caption" aria-live="polite"><span class="forest-name"></span><small class="forest-count"></small></div><button type="button" data-deck-step="1" aria-label="下一张卡牌"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></div></section>`}
function forestProjectHTML(p){return `<article class="project-card forest-project">${forestShowcaseHTML()}<div class="project-info"><p class="project-category">卡牌设计 / 动态效果</p><h3><button data-open="dark-forest">${escapeHTML(p.title)}</button></h3><p class="project-summary">宇宙文明主题卡牌与打击效果。</p></div></article>`}
function mountForestDecks(parent=document){for(const root of parent.querySelectorAll('.forest-deck')){if(root.dataset.mounted)continue;root.dataset.mounted='true';let current=Number(root.dataset.start)||0,down=null,suppress=false;const cards=[...root.querySelectorAll('.forest-card')],n=cards.length;const update=()=>{cards.forEach((card,i)=>{let delta=(i-current+n)%n;if(delta>n/2)delta-=n;const visible=Math.abs(delta)<=2;card.style.setProperty('--card-offset',cClamp(delta,-3,3));card.style.zIndex=String(10-Math.abs(delta));card.style.opacity=visible?'1':'0';card.style.pointerEvents=visible?'auto':'none';card.tabIndex=delta===0?0:-1;card.setAttribute('aria-hidden',String(delta!==0));card.classList.toggle('is-current',delta===0)});root.querySelector('.forest-name').textContent=FOREST_CARDS[current].title;root.querySelector('.forest-count').textContent=String(current+1).padStart(2,'0')+' / '+n;root.dataset.index=String(current)};const step=delta=>{current=(current+delta+n)%n;update()};root.querySelectorAll('[data-deck-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.deckStep)));cards.forEach((b,i)=>b.onclick=()=>{if(suppress){suppress=false;return}if(current!==i){current=i;update()}else if(!root.classList.contains('forest-deck-large'))openForest(current)});root.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1)}};const stage=root.querySelector('.forest-stage');stage.onpointerdown=e=>{down=e.clientX;suppress=false};stage.onpointerup=e=>{if(down!==null&&Math.abs(e.clientX-down)>35){suppress=true;step(e.clientX<down?1:-1)}down=null};stage.onpointercancel=()=>down=null;update();requestAnimationFrame(()=>root.classList.add('deck-ready'))}}
function openForest(start=0){document.querySelectorAll('.forest-showcase video').forEach(v=>v.pause());activeProject='dark-forest';const dialog=$('#project-dialog');dialog.classList.add('forest-dialog');$('#project-detail').innerHTML=`<div class="detail-content forest-detail"><p class="project-category">卡牌视觉</p><h2>黑暗森林</h2>${forestShowcaseHTML(true,start)}${legacyGalleryHTML(projectData().find(p=>p.id==='dark-forest'))}</div>`;if(!dialog.open)dialog.showModal();mountForestShowcases(dialog)}

const forestFilmURLs=new Map();
function forestFilmURL(index){return FOREST_FILMS[index].data}
function forestShowcaseHTML(detail=false,start=0){return `<section class="forest-showcase ${detail?'forest-showcase-large':''}" aria-label="黑暗森林作品"><div class="forest-view-switch" role="group" aria-label="展示内容"><button type="button" data-forest-view="cards" aria-pressed="true">卡牌设计</button><button type="button" data-forest-view="films" aria-pressed="false">打击效果 <span>03</span></button></div><div class="forest-view" data-forest-panel="cards">${forestDeckHTML(detail,start)}</div><div class="forest-view" data-forest-panel="films" hidden><div class="forest-films"><div class="forest-film-screen">${gifPreviewHTML(GIF_PREVIEWS['light-particle'],FOREST_FILMS[0].title,forestFilmURL(0))}</div><div class="forest-film-picker" role="group" aria-label="选择打击效果">${FOREST_FILMS.map((f,i)=>`<button type="button" data-film="${i}" aria-pressed="${i===0}">${previewImageHTML(f.poster,'')}<span>${f.title}</span></button>`).join('')}</div></div></div></section>`}
function mountForestShowcases(parent=document){mountForestDecks(parent);for(const root of parent.querySelectorAll('.forest-showcase')){if(root.dataset.mounted)continue;root.dataset.mounted='true';const names=['light-particle','annihilation','thermonuclear'];const load=index=>{root.querySelector('.forest-film-screen').innerHTML=gifPreviewHTML(GIF_PREVIEWS[names[index]],FOREST_FILMS[index].title,forestFilmURL(index));root.querySelectorAll('[data-film]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.film)===index)))};root.querySelectorAll('[data-forest-view]').forEach(button=>button.onclick=()=>{const next=button.dataset.forestView;root.querySelectorAll('[data-forest-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelectorAll('[data-forest-panel]').forEach(panel=>panel.hidden=panel.dataset.forestPanel!==next);if(next==='cards')mountForestDecks(root)});root.querySelectorAll('[data-film]').forEach(button=>button.onclick=()=>load(Number(button.dataset.film)))}}

