function seedBuiltinReferences(){for(const item of [...LEGACY_MEDIA,...BUILTIN_MEDIA])if(validKeys.has(item.key)&&!assets.has(item.key))assets.set(item.key,{url:item.data,name:item.name,type:item.type})}
async function init(){
  syncContentKeys();
  try{const raw=EMBEDDED_CONTENT;if(raw){state=normalizeState(raw.state);syncContentKeys();for(const item of raw.media||[])if(validKeys.has(item.key)&&MIME_TYPES.has(item.type))assets.set(item.key,{blob:fromDataURL(item.data,item.type),name:item.name,type:item.type})}}catch(error){console.warn('Embedded content unavailable',error)}
  seedBuiltinReferences();renderProjects();initializePortfolioModules();mountLegacyProfile();drawWave();document.body.dataset.ready='true';
  // Optional 3D work must never block the project list or local content recovery.
  requestAnimationFrame(()=>{try{mountPersonalAvatar()}catch(error){console.warn('Avatar enhancement unavailable',error)}});
  try{
    db=await dbPromise;const saved=await dbRead('state');
    if(saved){
      state=normalizeState(saved);syncContentKeys();
      const records=await Promise.all([...validKeys].map(async key=>[key,await dbRead('asset:'+key)]));
      assets=new Map(records.filter(([,asset])=>asset?.blob&&MIME_TYPES.has(asset.type)));
    }else{
      await new Promise((resolve,reject)=>{const tx=db.transaction('content','readwrite'),store=tx.objectStore('content');store.put(state,'state');for(const [key,item]of assets)if(item.blob)store.put(item,'asset:'+key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})
    }
    await seedLegacyMedia();renderProjects();
  }catch(error){console.warn('Local content recovery unavailable',error)}
}

init();
